script:
$ErrorActionPreference='Stop'
$taskRoot='C:/Users/poin/.codex/worktrees/1817/RMQ'
$taskHelper=Join-Path $taskRoot 'scripts/packed_native_identity.ps1'
if((Get-FileHash -LiteralPath $taskHelper).Hash -cne 'A21F67E2EDF49C8E218C657E73967E920EFB85FF025476E01BD04A83CA50B17A'){throw 'frozen helper mismatch'}
. $taskHelper
$taskPins=Get-Content (Join-Path $PSScriptRoot 'hash-small-file-pins.json') -Raw|ConvertFrom-Json
if($taskPins.files.Count -ne 100){throw 'exact sample count mismatch'}
$taskStarted=[DateTime]::UtcNow.ToString('o');$taskWatch=[Diagnostics.Stopwatch]::StartNew()
# Each supplied path is an exact existing leaf; no wider directory is scanned.
$taskActual=@(Get-NativeFileInventory $taskPins.root @($taskPins.files.path))
$taskWatch.Stop()
if($taskActual.Count -ne 100){throw 'actual sample count mismatch'}
foreach($taskRow in $taskActual){
  $taskExpected=@($taskPins.files|Where-Object path -CEQ $taskRow.path)
  if($taskExpected.Count -ne 1 -or $taskRow.bytes -ne $taskExpected[0].bytes -or $taskRow.sha256 -cne $taskExpected[0].sha256){throw ('exact sample row mismatch: '+$taskRow.path)}
}
$taskResult=[ordered]@{schema='native1-small-file-benchmark-v1';shell=$PSVersionTable.PSVersion.ToString();startedUTC=$taskStarted;completedUTC=[DateTime]::UtcNow.ToString('o');seconds=$taskWatch.Elapsed.TotalSeconds;pid=$PID;files=$taskActual.Count;bytes=$taskPins.bytes;pass=$true;helperSHA256=(Get-FileHash -LiteralPath $taskHelper).Hash;actual=$taskActual}
[IO.File]::WriteAllText((Join-Path $PSScriptRoot ('hash-small-file-result-'+$PSVersionTable.PSVersion.Major+'.json')),($taskResult|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
$taskResult.Remove('actual');$taskResult|ConvertTo-Json -Depth 5 -Compress|Write-Output
